import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabaseClient';

const perguntas = [
  "Qual é o seu nome completo e onde você nasceu?",
  "Como foi sua infância? Qual memória mais te marca?",
  "Quem foram as pessoas mais importantes da sua vida?",
  "Qual foi o momento mais difícil que você superou?",
  "Que conselho você daria para quem tem 20 anos?"
];

function Onboarding() {
  const navigate = useNavigate();
  const [etapa, setEtapa] = useState(0);
  const [resposta, setResposta] = useState('');
  const [loading, setLoading] = useState(false);

  const handleProximo = async () => {
    if (!resposta.trim()) return;
    setLoading(true);

    const { data: { user } } = await supabase.auth.getUser();

    await supabase.from('memorias').insert({
      user_id: user.id,
      pergunta: perguntas[etapa],
      resposta: resposta,
      tipo: 'onboarding'
    });

    setResposta('');
    setLoading(false);

    if (etapa < perguntas.length - 1) {
      setEtapa(etapa + 1);
    } else {
      navigate('/dashboard');
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'white',
      fontFamily: 'Georgia, serif',
      textAlign: 'center',
      padding: '30px'
    }}>
      <p style={{ opacity: 0.5, marginBottom: '10px' }}>
        {etapa + 1} de {perguntas.length}
      </p>
      <h2 style={{ fontSize: '1.6rem', marginBottom: '30px', maxWidth: '500px', lineHeight: 1.5 }}>
        {perguntas[etapa]}
      </h2>
      <textarea
        value={resposta}
        onChange={e => setResposta(e.target.value)}
        placeholder="Escreva sua resposta aqui..."
        rows={5}
        style={{
          width: '100%',
          maxWidth: '500px',
          padding: '15px',
          fontSize: '1rem',
          borderRadius: '15px',
          border: 'none',
          marginBottom: '20px',
          fontFamily: 'Georgia, serif',
          resize: 'none'
        }}
      />
      <button
        onClick={handleProximo}
        disabled={loading || !resposta.trim()}
        style={{
          background: 'white',
          color: '#1a1a2e',
          border: 'none',
          padding: '12px 40px',
          fontSize: '1rem',
          borderRadius: '25px',
          cursor: 'pointer',
          fontWeight: 'bold',
          opacity: resposta.trim() ? 1 : 0.5
        }}
      >
        {loading ? 'Salvando...' : etapa < perguntas.length - 1 ? 'Próximo →' : 'Concluir'}
      </button>
    </div>
  );
}

export default Onboarding;
